TITLE: Next.js Middleware with Rewrite and Matcher Configuration
DESCRIPTION: Demonstrates a basic Next.js Middleware that rewrites the URL and uses an exported `config` object with a `matcher` array to define specific paths for invocation. The Middleware file should be located next to the `pages` directory.

SOURCE: https://github.com/vercel/next.js/blob/canary/errors/middleware-upgrade-guide.mdx#_snippet_1

LANGUAGE: ts
CODE:
```
import { NextResponse } from 'next/server';
import type { NextRequest } from 'next/server';

export function middleware(request: NextRequest) {
  return NextResponse.rewrite(new URL('/about-2', request.url));
}

// Supports both a single string value or an array of matchers
export const config = {
  matcher: ['/about/:path*', '/dashboard/:path*'],
};
```

