"use client";

import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

export default function CreatePostPage() {
  const [title, setTitle] = useState("");
  const [content, setContent] = useState("");

  // Check if both fields have content to enable the Publish button
  const isFormValid = title.trim() !== "" && content.trim() !== "";

  const handlePublish = () => {
    if (isFormValid) {
      // Here you would typically send the data to your backend
      console.log("Publishing post:", { title, content });
      alert(`Post published!\n\nTitle: ${title}\nContent: ${content}`);

      // Optionally clear the form after publishing
      setTitle("");
      setContent("");
    }
  };

  return (
    <div className="max-w-2xl mx-auto p-6 space-y-6">
      <div className="space-y-2">
        <h1 className="text-3xl font-bold tracking-tight">Create New Post</h1>
        <p className="text-muted-foreground">
          Fill in the title and content below to create a new post.
        </p>
      </div>

      <div className="space-y-4">
        {/* Title Input */}
        <div className="space-y-2">
          <Label htmlFor="title">Title</Label>
          <Input
            id="title"
            type="text"
            placeholder="Enter your post title..."
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            className="w-full"
          />
          <p className="text-sm text-muted-foreground">
            {title.length === 0 && "Title is required"}
          </p>
        </div>

        {/* Content Input */}
        <div className="space-y-2">
          <Label htmlFor="content">Content</Label>
          <Input
            id="content"
            type="text"
            placeholder="Enter your post content..."
            value={content}
            onChange={(e) => setContent(e.target.value)}
            className="w-full min-h-[100px]"
          />
          <p className="text-sm text-muted-foreground">
            {content.length === 0 && "Content is required"}
          </p>
        </div>

        {/* Form Status */}
        <div className="text-sm text-muted-foreground">
          {!isFormValid && (
            <p className="text-orange-600">
              Please fill in both title and content to enable publishing.
            </p>
          )}
          {isFormValid && (
            <p className="text-green-600">
              Ready to publish! Both fields are filled.
            </p>
          )}
        </div>

        {/* Publish Button */}
        <div className="pt-4">
          <Button
            onClick={handlePublish}
            disabled={!isFormValid}
            className="w-full sm:w-auto"
            size="lg"
          >
            Publish Post
          </Button>
        </div>
      </div>

      {/* Preview Section */}
      <div className="mt-8 p-4 border rounded-lg bg-muted/50">
        <h2 className="text-lg font-semibold mb-3">Preview</h2>
        <div className="space-y-2">
          <div>
            <strong>Title:</strong> {title || <span className="text-muted-foreground">No title entered</span>}
          </div>
          <div>
            <strong>Content:</strong> {content || <span className="text-muted-foreground">No content entered</span>}
          </div>
        </div>
      </div>
    </div>
  );
}

// Alternative version using Textarea for content (more appropriate for longer content)
export function CreatePostWithTextarea() {
  const [title, setTitle] = useState("");
  const [content, setContent] = useState("");

  // Check if both fields have content to enable the Publish button
  const isFormValid = title.trim() !== "" && content.trim() !== "";

  const handlePublish = () => {
    if (isFormValid) {
      // Here you would typically send the data to your backend
      console.log("Publishing post:", { title, content });
      alert(`Post published!\n\nTitle: ${title}\nContent: ${content}`);

      // Optionally clear the form after publishing
      setTitle("");
      setContent("");
    }
  };

  return (
    <div className="max-w-2xl mx-auto p-6 space-y-6">
      <div className="space-y-2">
        <h1 className="text-3xl font-bold tracking-tight">Create New Post</h1>
        <p className="text-muted-foreground">
          Fill in the title and content below to create a new post.
        </p>
      </div>

      <div className="space-y-4">
        {/* Title Input */}
        <div className="space-y-2">
          <Label htmlFor="title">Title</Label>
          <Input
            id="title"
            type="text"
            placeholder="Enter your post title..."
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            className="w-full"
          />
        </div>

        {/* Content Textarea */}
        <div className="space-y-2">
          <Label htmlFor="content">Content</Label>
          <textarea
            id="content"
            placeholder="Enter your post content..."
            value={content}
            onChange={(e) => setContent(e.target.value)}
            className="w-full min-h-[150px] px-3 py-2 border border-input bg-background rounded-md text-sm ring-offset-background placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50"
          />
        </div>

        {/* Form Status */}
        <div className="flex items-center justify-between">
          <div className="text-sm text-muted-foreground">
            {!isFormValid ? (
              <span className="text-orange-600">
                Fill both fields to publish
              </span>
            ) : (
              <span className="text-green-600">
                Ready to publish
              </span>
            )}
          </div>

          <div className="text-sm text-muted-foreground">
            {title.length > 0 && content.length > 0 && (
              <span>{title.length + content.length} characters</span>
            )}
          </div>
        </div>

        {/* Publish Button */}
        <Button
          onClick={handlePublish}
          disabled={!isFormValid}
          className="w-full"
          size="lg"
        >
          {isFormValid ? "Publish Post" : "Fill in both fields"}
        </Button>
      </div>
    </div>
  );
}

