"use client";

import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";

interface PostData {
  title: string;
  content: string;
}

export default function CreatePostPage() {
  const [title, setTitle] = useState("");
  const [content, setContent] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Check if both fields have content to enable the Publish button
  // Using trim() to ensure empty whitespace doesn't count as valid content
  const isFormValid = title.trim() !== "" && content.trim() !== "";

  const handlePublish = async () => {
    if (!isFormValid) return;

    setIsSubmitting(true);

    try {
      // Here you would typically send the data to your backend
      const postData: PostData = {
        title: title.trim(),
        content: content.trim()
      };

      console.log("Publishing post:", postData);

      // Simulate API call
      await new Promise(resolve => setTimeout(resolve, 1000));

      alert(`Post published successfully!\n\nTitle: ${postData.title}\nContent: ${postData.content}`);

      // Clear the form after successful publishing
      setTitle("");
      setContent("");
    } catch (error) {
      console.error("Error publishing post:", error);
      alert("Failed to publish post. Please try again.");
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="max-w-2xl mx-auto p-6 space-y-6">
      <div className="space-y-2">
        <h1 className="text-3xl font-bold tracking-tight">Create New Post</h1>
        <p className="text-muted-foreground">
          Fill in the title and content below to create a new post.
        </p>
      </div>

      <div className="space-y-6">
        {/* Title Input */}
        <div className="space-y-2">
          <Label htmlFor="title">Title *</Label>
          <Input
            id="title"
            type="text"
            placeholder="Enter your post title..."
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            className="w-full"
          />
          <p className="text-sm text-muted-foreground">
            {title.trim() === "" && (
              <span className="text-orange-600">Title is required</span>
            )}
          </p>
        </div>

        {/* Content Input */}
        <div className="space-y-2">
          <Label htmlFor="content">Content *</Label>
          <Textarea
            id="content"
            placeholder="Enter your post content..."
            value={content}
            onChange={(e) => setContent(e.target.value)}
            className="w-full min-h-[150px] resize-y"
          />
          <p className="text-sm text-muted-foreground">
            {content.trim() === "" && (
              <span className="text-orange-600">Content is required</span>
            )}
          </p>
        </div>

        {/* Form Validation Status */}
        <div className="p-4 rounded-lg bg-muted/50">
          <div className="flex items-center justify-between">
            <div className="text-sm">
              {!isFormValid ? (
                <span className="text-orange-600 font-medium">
                  Please fill in both title and content to enable publishing.
                </span>
              ) : (
                <span className="text-green-600 font-medium">
                  ✓ Ready to publish! Both fields are filled.
                </span>
              )}
            </div>

            <div className="text-sm text-muted-foreground">
              {title.length > 0 && content.length > 0 && (
                <span>{(title + content).length} characters</span>
              )}
            </div>
          </div>
        </div>

        {/* Action Buttons */}
        <div className="flex gap-3 pt-4">
          <Button
            onClick={handlePublish}
            disabled={!isFormValid || isSubmitting}
            className="flex-1"
            size="lg"
          >
            {isSubmitting ? (
              <>
                <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-white mr-2"></div>
                Publishing...
              </>
            ) : (
              "Publish Post"
            )}
          </Button>

          <Button
            variant="outline"
            onClick={() => {
              setTitle("");
              setContent("");
            }}
            disabled={isSubmitting}
            size="lg"
          >
            Clear
          </Button>
        </div>
      </div>

      {/* Live Preview */}
      <div className="mt-8 p-4 border rounded-lg bg-muted/30">
        <h2 className="text-lg font-semibold mb-3">Live Preview</h2>
        <div className="space-y-3">
          <div>
            <strong className="text-sm text-muted-foreground">Title:</strong>
            <p className="mt-1">
              {title.trim() || (
                <span className="text-muted-foreground italic">No title entered</span>
              )}
            </p>
          </div>
          <div>
            <strong className="text-sm text-muted-foreground">Content:</strong>
            <p className="mt-1 whitespace-pre-wrap">
              {content.trim() || (
                <span className="text-muted-foreground italic">No content entered</span>
              )}
            </p>
          </div>
        </div>
      </div>
    </div>
  );
}

// Alternative simplified version with just the core functionality
export function SimpleCreatePost() {
  const [title, setTitle] = useState("");
  const [content, setContent] = useState("");

  // Simple validation - button is disabled if either field is empty
  const canPublish = title.trim() !== "" && content.trim() !== "";

  const handlePublish = () => {
    if (canPublish) {
      console.log("Publishing:", { title: title.trim(), content: content.trim() });
      alert("Post published successfully!");
      // Clear form
      setTitle("");
      setContent("");
    }
  };

  return (
    <div className="max-w-xl mx-auto p-6 space-y-6">
      <h1 className="text-2xl font-bold">Create Post</h1>

      <div className="space-y-4">
        <div className="space-y-2">
          <Label htmlFor="title">Title</Label>
          <Input
            id="title"
            placeholder="Post title"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
          />
        </div>

        <div className="space-y-2">
          <Label htmlFor="content">Content</Label>
          <Textarea
            id="content"
            placeholder="Post content"
            value={content}
            onChange={(e) => setContent(e.target.value)}
            className="min-h-[120px]"
          />
        </div>

        <Button 
          onClick={handlePublish}
          disabled={!canPublish}
          className="w-full"
        >
          {!canPublish ? "Fill both fields to publish" : "Publish Post"}
        </Button>
      </div>
    </div>
  );
}

